package com.projecthero.mod.client.greenlantern.mech;

import com.projecthero.mod.ProjectHeroMod;
import com.projecthero.mod.greenlantern.mech.HardLightMechEntity;

import net.minecraft.resources.ResourceLocation;
import net.minecraft.util.Mth;
import net.minecraft.world.phys.Vec3;

import software.bernie.geckolib.animation.AnimationState;
import software.bernie.geckolib.model.GeoModel;

/** v0.17.1: the Hard-Light Mech's GeckoLib model (generated by scratchpad/gl_mech_v0171/gen_gl_mech.js). */
public class HardLightMechModel extends GeoModel<HardLightMechEntity> {
	public static final ResourceLocation GEO = ProjectHeroMod.id("geo/green_lantern_mech.geo.json");
	public static final ResourceLocation TEXTURE = ProjectHeroMod.id("textures/entity/green_lantern/mech.png");
	public static final ResourceLocation GLOW = ProjectHeroMod.id("textures/entity/green_lantern/mech_glow.png");
	public static final ResourceLocation ANIMATION = ProjectHeroMod.id("animations/green_lantern_mech.animation.json");

	@Override
	public ResourceLocation getModelResource(HardLightMechEntity animatable) {
		return GEO;
	}

	@Override
	public ResourceLocation getTextureResource(HardLightMechEntity animatable) {
		return TEXTURE;
	}

	@Override
	public ResourceLocation getAnimationResource(HardLightMechEntity animatable) {
		return ANIMATION;
	}

	/**
	 * v0.17.1: the Giga Drill follows the pilot's aim -- while it spins up (and along the locked line while it charges) the
	 * drill arm tips up / down with the aim's pitch, on top of the clip (both drill clips key the arm every frame).
	 */
	@Override
	public void setCustomAnimations(HardLightMechEntity m, long instanceId, AnimationState<HardLightMechEntity> state) {
		if (m.move() == HardLightMechEntity.MOVE_CANNON && m.moveTicks() < 26) {
			// v0.17.1 round 2: the Lantern Cannon arm tips up / down with the pilot's aim while it charges and fires
			Vec3 aim = m.moveDir();
			float pc = Mth.clamp((float) Math.asin(Mth.clamp(aim.y, -1.0, 1.0)), -0.8f, 0.8f);
			getBone("arm_l").ifPresent(b -> b.setRotX(b.getRotX() + pc));
		}
		int d = m.drillState();
		if (d != HardLightMechEntity.DRILL_SPIN && d != HardLightMechEntity.DRILL_CHARGE) {
			return;
		}
		Vec3 dir = m.drillDir();
		// radians: GeckoLib bone X runs opposite to the clip convention, so aiming down (dir.y < 0) is a negative add
		float pitch = (float) Math.asin(Mth.clamp(dir.y, -1.0, 1.0));
		pitch = Mth.clamp(pitch, -0.7f, 0.7f);
		float p = pitch;
		getBone("arm_r").ifPresent(b -> b.setRotX(b.getRotX() + p));
	}
}
